-- Expose the existing safety-gated Mailbox through a participant-safe player workspace.
alter table public.mailbox_threads add column if not exists subject text not null default 'Conversation';
alter table public.mailbox_threads add column if not exists participant_one_read_at timestamptz;
alter table public.mailbox_threads add column if not exists participant_two_read_at timestamptz;
alter table public.mailbox_threads add column if not exists participant_one_archived boolean not null default false;
alter table public.mailbox_threads add column if not exists participant_two_archived boolean not null default false;
update public.mailbox_threads set participant_one_read_at=coalesce(participant_one_read_at,updated_at),participant_two_read_at=coalesce(participant_two_read_at,updated_at);
create index if not exists mailbox_messages_thread_activity_idx on public.mailbox_messages(thread_id,created_at desc);

create or replace function public.get_mailbox_unread_count()returns bigint language plpgsql stable security definer set search_path=public as $$declare result bigint;begin perform require_social_eligibility();select count(*)into result from mailbox_messages m join mailbox_threads t on t.id=m.thread_id where auth.uid()in(t.participant_one,t.participant_two)and m.sender_id<>auth.uid()and m.created_at>coalesce(case when auth.uid()=t.participant_one then t.participant_one_read_at else t.participant_two_read_at end,'epoch'::timestamptz);return result;end$$;

create or replace function public.get_mailbox(p_box text default'inbox')returns jsonb language plpgsql stable security definer set search_path=public as $$declare result jsonb;begin perform require_social_eligibility();if p_box not in('inbox','sent')then raise exception'Invalid Mailbox view';end if;select coalesce(jsonb_agg(row_data order by (row_data->>'updated_at')::timestamptz desc),'[]'::jsonb)into result from(select jsonb_build_object('id',t.id,'subject',t.subject,'other_id',other.id,'other_name',other.name,'other_username',other.username,'other_account_number',other.account_number,'updated_at',t.updated_at,'preview',left(last_message.body,120),'last_sender_id',last_message.sender_id,'unread_count',(select count(*)from mailbox_messages unread where unread.thread_id=t.id and unread.sender_id<>auth.uid()and unread.created_at>coalesce(case when auth.uid()=t.participant_one then t.participant_one_read_at else t.participant_two_read_at end,'epoch'::timestamptz)))row_data from mailbox_threads t join stables other on other.id=case when auth.uid()=t.participant_one then t.participant_two else t.participant_one end join lateral(select m.body,m.sender_id,m.created_at from mailbox_messages m where m.thread_id=t.id order by m.created_at desc limit 1)last_message on true where auth.uid()in(t.participant_one,t.participant_two)and not(case when auth.uid()=t.participant_one then t.participant_one_archived else t.participant_two_archived end)and((p_box='inbox'and exists(select 1 from mailbox_messages m where m.thread_id=t.id and m.sender_id<>auth.uid()))or(p_box='sent'and exists(select 1 from mailbox_messages m where m.thread_id=t.id and m.sender_id=auth.uid()))))x;return result;end$$;

create or replace function public.get_mailbox_thread(p_thread uuid)returns jsonb language plpgsql security definer set search_path=public as $$declare t mailbox_threads;other stables;messages jsonb;begin perform require_social_eligibility();select*into t from mailbox_threads where id=p_thread and auth.uid()in(participant_one,participant_two)for update;if t.id is null then raise exception'Conversation not found';end if;if auth.uid()=t.participant_one then update mailbox_threads set participant_one_read_at=now(),participant_one_archived=false where id=t.id;else update mailbox_threads set participant_two_read_at=now(),participant_two_archived=false where id=t.id;end if;select*into other from stables where id=case when auth.uid()=t.participant_one then t.participant_two else t.participant_one end;select coalesce(jsonb_agg(jsonb_build_object('id',m.id,'sender_id',m.sender_id,'body',m.body,'created_at',m.created_at)order by m.created_at),'[]'::jsonb)into messages from mailbox_messages m where m.thread_id=t.id;return jsonb_build_object('id',t.id,'subject',t.subject,'other_id',other.id,'other_name',other.name,'other_username',other.username,'other_account_number',other.account_number,'messages',messages);end$$;

create or replace function public.search_mailbox_players(p_query text)returns jsonb language plpgsql stable security definer set search_path=public as $$declare result jsonb;begin perform require_social_eligibility();if length(trim(coalesce(p_query,'')))<2 then return'[]'::jsonb;end if;select coalesce(jsonb_agg(jsonb_build_object('id',s.id,'username',s.username,'stable_name',s.name,'account_number',s.account_number)order by s.username nulls last,s.account_number),'[]'::jsonb)into result from(select*from stables s where s.id<>auth.uid()and account_social_eligible(s.id)and(s.username ilike'%'||trim(p_query)||'%'or s.name ilike'%'||trim(p_query)||'%'or s.account_number::text=trim(p_query))order by s.account_number limit 12)s;return result;end$$;

create or replace function public.get_mailbox_recipient(p_account uuid)returns jsonb language plpgsql stable security definer set search_path=public as $$declare s stables;begin perform require_social_eligibility();select*into s from stables where id=p_account and id<>auth.uid()and account_social_eligible(id);if s.id is null then raise exception'Recipient is unavailable';end if;return jsonb_build_object('id',s.id,'username',s.username,'stable_name',s.name,'account_number',s.account_number);end$$;

drop function if exists public.send_mailbox_message(uuid,text,uuid);
create function public.send_mailbox_message(p_recipient uuid,p_body text,p_thread uuid default null,p_subject text default null)returns jsonb language plpgsql security definer set search_path=public as $$declare decision jsonb;thread mailbox_threads;message mailbox_messages;one_id uuid;two_id uuid;last_time timestamptz;clean_subject text:=left(trim(regexp_replace(coalesce(p_subject,'Conversation'),'<[^>]*>','','g')),120);begin perform require_social_eligibility();if p_recipient=auth.uid()or not account_social_eligible(p_recipient)then raise exception'Recipient is unavailable';end if;if exists(select 1 from player_blocks where(blocker_id=auth.uid()and blocked_id=p_recipient)or(blocker_id=p_recipient and blocked_id=auth.uid()))then raise exception'Messaging is unavailable for this player';end if;if length(trim(coalesce(p_body,'')))not between 1 and 3000 then raise exception'Message must be 1–3,000 characters';end if;if p_thread is null and length(clean_subject)not between 1 and 120 then raise exception'Subject is required';end if;select max(created_at)into last_time from mailbox_messages where sender_id=auth.uid();if last_time>now()-interval'3 seconds'then raise exception'Please wait before sending another message';end if;decision:=moderate_player_content(concat_ws(' ',clean_subject,p_body),'mailbox_message',auth.uid(),null,jsonb_build_object('recipient_id',p_recipient));if decision->>'action'='unavailable'then return jsonb_build_object('delivered',false,'message','Unable to send right now. Please try again shortly.');elsif decision->>'action'<>'allow'then return jsonb_build_object('delivered',false,'category',decision->>'category','message','This message can’t be sent because it may violate Legacy Equine’s Community Standards. Please revise it and try again.');end if;one_id:=least(auth.uid()::text,p_recipient::text)::uuid;two_id:=greatest(auth.uid()::text,p_recipient::text)::uuid;if p_thread is not null then select*into thread from mailbox_threads where id=p_thread and auth.uid()in(participant_one,participant_two)and p_recipient in(participant_one,participant_two)for update;end if;if thread.id is null then insert into mailbox_threads(participant_one,participant_two,subject,participant_one_read_at,participant_two_read_at)values(one_id,two_id,clean_subject,case when auth.uid()=one_id then now()end,case when auth.uid()=two_id then now()end)on conflict(participant_one,participant_two)do update set subject=excluded.subject,updated_at=now()returning*into thread;end if;insert into mailbox_messages(thread_id,sender_id,body)values(thread.id,auth.uid(),left(trim(regexp_replace(p_body,'<[^>]*>','','g')),3000))returning*into message;update mailbox_threads set updated_at=now(),participant_one_read_at=case when auth.uid()=participant_one then now()else participant_one_read_at end,participant_two_read_at=case when auth.uid()=participant_two then now()else participant_two_read_at end,participant_one_archived=case when p_recipient=participant_one then false else participant_one_archived end,participant_two_archived=case when p_recipient=participant_two then false else participant_two_archived end where id=thread.id;return jsonb_build_object('delivered',true,'thread_id',thread.id,'message_id',message.id);end$$;

create or replace function public.archive_mailbox_thread(p_thread uuid,p_archive boolean default true)returns void language plpgsql security definer set search_path=public as $$declare t mailbox_threads;begin perform require_social_eligibility();select*into t from mailbox_threads where id=p_thread and auth.uid()in(participant_one,participant_two)for update;if t.id is null then raise exception'Conversation not found';end if;if auth.uid()=t.participant_one then update mailbox_threads set participant_one_archived=p_archive where id=t.id;else update mailbox_threads set participant_two_archived=p_archive where id=t.id;end if;end$$;

revoke all on function public.get_mailbox_unread_count(),public.get_mailbox(text),public.get_mailbox_thread(uuid),public.search_mailbox_players(text),public.get_mailbox_recipient(uuid),public.send_mailbox_message(uuid,text,uuid,text),public.archive_mailbox_thread(uuid,boolean)from public;
grant execute on function public.get_mailbox_unread_count(),public.get_mailbox(text),public.get_mailbox_thread(uuid),public.search_mailbox_players(text),public.get_mailbox_recipient(uuid),public.send_mailbox_message(uuid,text,uuid,text),public.archive_mailbox_thread(uuid,boolean)to authenticated;
